package com.github.nyabanban.fuji.emulator.components.sdhost

import com.github.nyabanban.fuji.emulator.api.*
import org.junit.jupiter.api.Test
import java.nio.file.Path
import kotlin.test.*

class SdInitHostTest {
 private fun input():Map<String,Any?> = mapOf("schema" to 1,"profile" to SdHostFactory.INIT_PROFILE,"initialRegisters" to(0..1).associate{it.toString() to SdControlHost.fields.associateWith{0L}},"clocks" to(0..3).associate{SdClockHost.key(it) to mapOf("initialWord" to 0,"bit1Samples" to listOf(0,1))},"initWords" to(0..1).associate{s->s.toString() to SdInitHost.fields.mapIndexed{f,n->n to(if(f<3)0x80000000L+s*4096+f else 0xa500L+s*256+f)}.toMap()})
 private class Context(var data:Map<String,Any?>):ComponentContext {
  var tick=10L;var reads=0;val entries=mutableMapOf<String,Any>();override val directory=Path.of("unused-sd-init")
  override val clock=EmulationClock{tick}
  override val ports=object:Ports{override fun<T:Any>register(owner:String,name:String,type:Class<T>,port:T){check(entries.putIfAbsent(name,port)==null)};override fun<T:Any>find(name:String,type:Class<T>):T?=entries[name]?.let{type.cast(it)};override fun removeOwner(owner:String)=error("unexpected remove")}
  override val events=object:EventChannel{override fun publish(event:ComponentEvent)=error("no invented IRQ");override fun subscribe(listener:(ComponentEvent)->Unit):AutoCloseable=error("no subscriptions")}
  override fun dataPath(relative:String)=directory.resolve(relative)
  override fun readData(relative:String):Map<String,Any?>{reads++;return data}
 }
 private fun create(c:Context):HardwareComponent {val f=SdHostFactory();return f.create(c,f.descriptor.settings.associate{it.key to it.default}+mapOf("profile" to SdHostFactory.INIT_PROFILE,"inputFile" to "init.yaml"))}
 private fun port(c:Context,s:Int,f:Int)=c.ports.find(SdInitHost.port(s,f),MmioDevice::class.java)!!
 @Test fun fourteenFieldsRemainIndependentAndOldProjectionUnchanged(){val c=Context(input());c.entries["cpu.execution-location"]=ExecutionLocationSource{ExecutionLocation(2,0x5afb0)};val h=create(c);h.start();val old=h.state()["clockState"];assertEquals(1,c.reads);assertEquals(28,h.additionalMmioPorts().size);assertEquals((0..27).toSet(),c.entries.values.filterIsInstance<MmioDevice>().map{it.clockIndex}.toSet());for(s in 0..1)for(f in 0..6){val p=port(c,s,f);if(f<3)assertEquals(0x80000000L+s*4096+f,p.read(0,4))else{p.write(0,2,0x55aaL+s*16+f);if(f>=5)assertEquals(0x55aaL+s*16+f,p.read(0,2))}};assertEquals(old,h.state()["clockState"]);assertTrue(h.interruptRoutes().isEmpty());assertEquals(false,h.state()["cardProtocolQualified"])}
 @Test fun missingMalformedInputsOldProjectionAndAllAliasesRefuseBeforePublication(){val base=input();val words=base["initWords"]as Map<*,*>;val row=words["0"]as Map<*,*>;val invalid=mutableListOf<Map<String,Any?>>();for(k in base.keys)invalid+=base-k;invalid+=base+mapOf("schema" to 1.0);invalid+=base+mapOf("extra" to 0);invalid+=base+mapOf("initWords" to(words-"1"));for(k in SdInitHost.fields)invalid+=base+mapOf("initWords" to(words+mapOf("0" to(row-k))));for((k,v)in listOf("capability6244" to -1L,"capability6244" to 0x100000000L,"present4024" to 1.0,"present6224" to true,"signal6238" to 65536L,"block4006" to "0","host6228" to null,"host4028" to -1L))invalid+=base+mapOf("initWords" to(words+mapOf("0" to(row+mapOf(k to v)))));invalid+=base+mapOf("clocks" to emptyMap<String,Any>());invalid+=base+mapOf("initialRegisters" to emptyMap<String,Any>());for(data in invalid){val c=Context(data);assertFails{create(c)};assertTrue(c.entries.isEmpty())};val names=(0..1).flatMap{s->(0..4).map{SdControlHost.port(s,it)}}+(0..3).map{SdClockHost.port(it)}+(0..1).flatMap{s->(0..6).map{SdInitHost.port(s,it)}};for(name in names){val c=Context(base);c.entries[name]=object:MmioDevice{override fun read(offset:Long,size:Int)=0L;override fun write(offset:Long,size:Int,value:Long){}};assertFails{create(c)};assertEquals(1,c.entries.size)}}
 @Test fun exactWidthsDirectionsOffsetsAndU16ValuesRejectAtomically(){val c=Context(input());val h=create(c);val before=h.state();for(s in 0..1)for(f in 0..6){val p=port(c,s,f);val width=if(f<3)4 else 2;for(w in listOf(0,1,2,4,8)){if(w!=width||f==3||f==4){assertFails{p.read(0,w)};assertEquals(before,h.state())};if(w!=width||f<3){assertFails{p.write(0,w,0)};assertEquals(before,h.state())}};for(off in listOf(-1L,1L,2L,4L)){assertFails{p.read(off,width)};assertFails{p.write(off,width,0)};assertEquals(before,h.state())};if(f>=3)for(v in listOf(-1L,65536L)){assertFails{p.write(0,2,v)};assertEquals(before,h.state())}}}
 @Test fun clockAndExecutionLocationFailuresPrecedeReadsWritesAndDiagnostics(){val c=Context(input());val h=create(c);val before=h.state();c.tick=-1;assertFails{port(c,0,0).read(0,4)};assertFails{port(c,1,5).write(0,2,1)};assertEquals(before,h.state());c.tick=1;c.entries["cpu.execution-location"]=ExecutionLocationSource{error("location failed")};assertFails{port(c,1,2).read(0,4)};assertFails{port(c,0,6).write(0,2,1)};assertEquals(before,h.state())}
 @Test fun inputSnapshotsBoundedDiagnosticsLifecycleAndRestartStayExplicit(){val base=input();val words=(base["initWords"]as Map<*,*>).entries.associate{it.key.toString() to(it.value as Map<*,*>).entries.associate{it.key.toString() to it.value}.toMutableMap()};val c=Context(base+mapOf("initWords" to words));val h=create(c);val initial=h.state()["initialInitWords"];words.getValue("0")["capability6244"]=0;assertEquals(initial,h.state()["initialInitWords"]);repeat(300){assertEquals(0x80000000L,port(c,0,0).read(0,4))};assertEquals(300L,h.state()["initReadCount"]);assertEquals(256,(h.state()["initAccesses"]as List<*>).size);assertEquals(true,h.state()["initAccessLogTruncated"]);h.applySettings(mapOf("profile" to SdHostFactory.INIT_PROFILE));assertFails{h.applySettings(mapOf("inputFile" to "other.yaml"))};h.close();h.close();assertFails{h.start()};assertFails{port(c,0,0).read(0,4)};assertFails{port(c,0,3).write(0,2,0)};assertFails{c.ports.find(SdClockHost.port(0),MmioDevice::class.java)!!.read(0,2)};assertFails{c.ports.find(SdControlHost.port(0,0),MmioDevice::class.java)!!.read(0,4)}}
}
